-- Aurora Fake Sky + Mahiru SFX - iPad/Delta All-In-One V1
local write=writefile
local custom=getcustomasset or getsynasset
if not(write and custom)then warn("[AURORA] asset APIs unavailable")return end

local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function dec(data)
 data=data:gsub('[^'..b..'=]','')
 return (data:gsub('.',function(x)
  if x=='=' then return '' end
  local r,f='',b:find(x,1,true)-1
  for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
  return r
 end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
  if #x~=8 then return '' end
  local c=0
  for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end
  return string.char(c)
 end))
end

local DATA={
bk=[[]],
dn=[[]],
ft=[[]],
lf=[[]],
rt=[[]],
up=[[]],
}
}
local props={bk="SkyboxBk",dn="SkyboxDn",ft="SkyboxFt",lf="SkyboxLf",rt="SkyboxRt",up="SkyboxUp"}
local assets={}
for _,f in ipairs({"bk","dn","ft","lf","rt","up"})do
 local ok,a=pcall(function()
  local fn="aurora_"..f..".tex"
  write(fn,dec(DATA[f]))
  return custom(fn)
 end)
 if ok then assets[f]=a else warn("[AURORA] "..f.." failed: "..tostring(a))end
 task.wait(.08)
end

local L=game:GetService("Lighting")
local function sky()
 local s=L:FindFirstChildOfClass("Sky")
 if not s then s=Instance.new("Sky");s.Name="AuroraFakeSky";s.Parent=L end
 for f,a in pairs(assets)do if a then pcall(function()s[props[f]]=a end)end end
end
sky()
L.ChildAdded:Connect(function(o)if o:IsA("Sky")then task.delay(.2,sky)end end)
task.spawn(function()for _,t in ipairs({.5,1.5,3,6,10})do task.wait(t);sky()end end)

-- Exact Mahiru SFX mappings from the working Mahiru pack.
local function mp3(file,url)
 local ok,a=pcall(function()
  local body=game:HttpGet(url)
  write(file,body)
  return custom(file)
 end)
 if ok then return a end
 warn("[AURORA SFX] "..tostring(a))
end
local kill=mp3("aurora_mahiru_kill.mp3","https://raw.githubusercontent.com/crypt0knifer-111/Texture-mahiru/79f7b5e755740e45fa06d37d0e6a223418505d40/a-la-a-la.mp3")
local move=mp3("aurora_mahiru_move.mp3","https://raw.githubusercontent.com/crypt0knifer-111/Mp3-s/4abce95151973a5ba6464d502712e28c980cd5f4/sounder.MP3")

local function id(v)
 if type(v)~="string"then return end
 return v:match("rbxassetid://(%d+)")or v:match("[?&]id=(%d+)")or v:match("(%d+)")
end
local map={}
if kill then map["16530229616"]=kill;map["16530229541"]=kill;map["16530229695"]=kill end
if move then map["16737738420"]=move;map["16770456156"]=move;map["16492958314"]=move end
local function patch(o)
 if not o:IsA("Sound")then return end
 local r=map[id(o.SoundId)]
 if r then pcall(function()o.SoundId=r end)end
end
for i,o in ipairs(game:GetDescendants())do patch(o);if i%500==0 then task.wait()end end
game.DescendantAdded:Connect(function(o)task.defer(function()if o.Parent then patch(o)end end)end)

pcall(function()
 game:GetService("StarterGui"):SetCore("SendNotification",{Title="Aurora Fake Sky",Text="Sky + Mahiru SFX loaded",Duration=6})
end)
